sign 14 5 "THE CRUCIBLE. Hall of Wagers above. No weapons drawn on the dock. No sums owed carried off the isle."
read 7 8 "The cable winch. The line runs down into the cloud, toward the Ninefold Shrine far below."
npc n38_dockhand 9 12 right sprite=worker talk=N38_DOCKHAND name="Dock-Warden Hesper"
npc n38_tout 21 7 down sprite=noble talk=N38_TOUT name="A Tout"
npc n38_p_pilot 26 13 left sprite=pilot talk=N38_P_PILOT if=phase:post

